function validate([time]) {
  if (typeof time !== 'string' || !/^[0-9?]{2}:[0-9?]{2}$/.test(time)) return 'time must look like hh:mm, using digits or ?.';
  for (let minutes = 0; minutes < 24 * 60; minutes++) {
    const candidate = String(Math.floor(minutes / 60)).padStart(2, '0') + ':' + String(minutes % 60).padStart(2, '0');
    if ([...time].every((ch, i) => ch === '?' || ch === candidate[i])) return null;
  }
  return 'No valid time can be made from this pattern.';
}

