  const digits = time.split('');

  if (digits[0] === '?') {
    digits[0] = digits[1] === '?' || digits[1] <= '3' ? '2' : '1';
  }
  if (digits[1] === '?') {
    digits[1] = digits[0] === '2' ? '3' : '9';
  }
  if (digits[3] === '?') {
    digits[3] = '5';
  }
  if (digits[4] === '?') {
    digits[4] = '9';
  }
  return digits.join('');
}

