function generate(rand, size) {
  const hours = Math.floor(rand() * 24);
  const minutes = Math.floor(rand() * 60);
  const base = String(hours).padStart(2, '0') + ':' + String(minutes).padStart(2, '0');
  const hideRate = size === 'large' ? 0.5 : rand();
  let time = '';
  for (let i = 0; i < 5; i++) time += i !== 2 && rand() < hideRate ? '?' : base[i];
  return [time];
}
